-- Run only with the release's matching application rollback. Aborts on later CMS edits.
begin;
set local lock_timeout='10s';
select pg_advisory_xact_lock(hashtextextended('theory-display-id',0));
select pg_advisory_xact_lock(hashtextextended('theory-knowledge-network',0));
lock table public.theories,public.techniques,public.theory_relations in share row exclusive mode;
do $guard$ begin
 if (select count(*) from private.theory_reform_backups where phase='theory-release-20261018-after' and source_table='theories')<>989 then raise exception 'Release backup missing';end if;
 if exists(select 1 from public.theories t full join (select * from private.theory_reform_backups where phase='theory-release-20261018-after' and source_table='theories') b on t.id=b.source_id where (to_jsonb(t)-'updated_at'-'updated_by') is distinct from (b.snapshot-'updated_at'-'updated_by')) then raise exception 'Later theory edit; manual rollback review required';end if;
 if exists(select 1 from private.theory_reform_backups b left join public.techniques t on t.id=b.source_id where b.phase='theory-release-20261018-after' and b.source_table='techniques' and to_jsonb(t) is distinct from b.snapshot) then raise exception 'Later technique edit';end if;
