-- Archive new stable IDs to retain references from personal saved/history data.
update public.theories set status='archived',display_id=null,display_order=null,updated_at=now() where id in(select jsonb_array_elements_text('["kb_957","kb_958","kb_959","kb_960","kb_961","kb_962","kb_963","kb_964","kb_965","kb_966","kb_967","kb_968","kb_969","kb_970","kb_971","kb_972","kb_973","kb_974","kb_975","kb_976","kb_977","kb_978","kb_979","kb_980","kb_981","kb_982","kb_983","kb_984","kb_985","kb_986","kb_987","kb_988","kb_989","kb_990","kb_991","kb_992","kb_993","kb_994","kb_995","kb_996","kb_997","kb_998","kb_999","kb_1000","kb_1001","kb_1002","kb_1003","kb_1004","kb_1005","kb_1006","kb_1007","kb_1008","kb_1009","kb_1010","kb_1011","kb_1012","kb_1013","kb_1014","kb_1015","kb_1016","kb_1017","kb_1018","kb_1019","kb_1020","kb_1021","kb_1022","kb_1023","kb_1024","kb_1025","kb_1026","kb_1027","kb_1028","kb_1029","kb_1030","kb_1031","kb_1032","kb_1033","kb_1034","kb_1035","kb_1036","kb_1037","kb_1038","kb_1039","kb_1040","kb_1041","kb_1042","kb_1043","kb_1044","kb_1045","kb_1046","kb_1047","kb_1048","kb_1049","kb_1050","kb_1051","kb_1052","kb_1053","kb_1054","kb_1055","kb_1056","kb_1057","kb_1058","kb_1059","kb_1060","kb_1061","kb_1062","kb_1063","kb_1064","kb_1065","kb_1066","kb_1067","kb_1068","kb_1069","kb_1070","kb_1071","kb_1072","kb_1073","kb_1074","kb_1075","kb_1076","kb_1077","kb_1078","kb_1079","kb_1080"]'::jsonb));
update public.theories t set aliases=b.snapshot->'aliases',related_theory_ids=b.snapshot->'related_theory_ids',display_id=(b.snapshot->>'display_id')::integer,display_order=(b.snapshot->>'display_order')::integer,taxonomy_order=(b.snapshot->>'taxonomy_order')::integer,updated_at=now() from private.theory_reform_backups b where b.phase='theory-release-20261018' and b.source_table='theories' and t.id=b.source_id;
set constraints all immediate;
do $verify$ begin if (select count(*) from public.theories where status='published')<>821 or (select count(*) from public.theory_relations)<>574 then raise exception 'Rollback totals differ';end if;end $verify$;
commit;
